{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Abiraterone, a steroidal CYP17 inhibitor structurally close to the query, has an estimated absolute oral bioavailability <10% in humans in the fasted state, directly supporting a low F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Fulvestrant, a steroidal estrogen receptor degrader with a phenolic hydroxyl like the query, has low oral bioavailability and requires intramuscular administration, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Testosterone undecanoate, a lipophilic steroid ester, showed absolute oral bioavailability of only 6.83 ± 3.32% in young women, indicating that even lipophilic steroids often have low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "β-Sitosterol, a sterol with a similar fused-ring scaffold, had an absolute oral bioavailability of 0.41% in healthy humans, consistent with low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Danazol in the fasted state had absolute bioavailability of 13%, below the 20% threshold, showing that a steroid can be low F without food or lipid formulation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Danazol in a fed-state emulsion reached 65% absolute bioavailability, demonstrating that formulation and food can raise F for some lipophilic steroids; this is contradictory to a blanket low-F conclusion but has limited transferability to the more polar, multi-hydroxyl query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a polar polyhydroxylated steroid; multiple high-transfer human absolute-bioavailability records for close steroidal analogues (abiraterone <10%, fulvestrant low, testosterone undecanoate ~7%, β-sitosterol 0.4%, fasted danazol 13%) consistently indicate F <20%. The only high-F record (fed danazol emulsion) is formulation-dependent and structurally less applicable, so the overall prediction is low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "No query-specific solubility, permeability, or first-pass metabolism data.",
    "Food/formulation effects on the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

